def product_Equal(n):
    # Convertir el número a una lista de dígitos
    digits = [int(d) for d in str(n)]

    # Calcular el producto de los dígitos en posiciones pares
    product_even = 1
    for i in range(len(digits)):
        if i % 2 == 0:
            product_even *= digits[i]

    # Calcular el producto de los dígitos en posiciones impares
    product_odd = 1
    for i in range(len(digits)):
        if i % 2 != 0:
            product_odd *= digits[i]

    # Verificar si el producto de los dígitos en posiciones pares es igual o no al producto de los dígitos en posiciones impares
    return product_even == product_odd

