def get_max_sum(n):
    memo = {}

    def dp(n):
        if n in memo:
            return memo[n]
        if n == 1:
            return 1
        max_sum = 0
        for i in range(2, n + 1):
            max_sum = max(max_sum, i + dp(n // i))
        memo[n] = max_sum
        return max_sum

    return dp(n)

def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

