def lbs(arr):
    n = len(arr)
    dp = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for i in range(n - 1):
        if arr[i] < arr[i + 1]:
            dp[i][i + 1] = 2 + dp[i][i]
        else:
            dp[i][i + 1] = 1
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if arr[i] < arr[j]:
                dp[i][j] = 2 + dp[i][j - 1]
            else:
                dp[i][j] = 1 + max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

